#!/usr/bin/env python3
"""Report declared kit reservations; no delivery or source mutation."""
import argparse,json,sys
from pathlib import Path

def report(path):
    raw=Path(path).read_bytes()
    if len(raw)>1048576: raise ValueError("input exceeds 1 MiB")
    data=json.loads(raw)
    if not isinstance(data,dict) or set(data)!={"schema_version","reservation_rows","attendance","release_status"}: raise ValueError("unexpected source fields")
    if type(data["schema_version"]) is not int or data["schema_version"]!=1: raise ValueError("unsupported version")
    rows=data["reservation_rows"]
    if not isinstance(rows,list) or not 1<=len(rows)<=10000: raise ValueError("nonempty bounded reservation_rows required")
    seen=set();total=0
    for row in rows:
        if not isinstance(row,dict) or set(row)!={"code","reserved"}: raise ValueError("invalid reservation row")
        if not isinstance(row["code"],str) or not row["code"].strip() or row["code"] in seen: raise ValueError("unique nonempty code required")
        n=row["reserved"]
        if type(n) is not int or n<0 or n>1000000: raise ValueError("reserved must be a bounded nonnegative integer")
        seen.add(row["code"]);total+=n
    attendance=data["attendance"]
    if attendance is not None and (type(attendance) is not int or attendance<0): raise ValueError("attendance must be null or a nonnegative count")
    if data["release_status"] not in ("unknown","withheld","declared-approved"): raise ValueError("invalid declared release status")
    return {"reserved_kits":total,"attendance":attendance,"release_status":data["release_status"],"source_rows":len(rows),"delivery_performed":False,"limits":"Source declarations are not authenticated approval or proof of attendance."}

def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument("source");a=p.parse_args()
    try: print(json.dumps(report(a.source),sort_keys=True));return 0
    except (OSError,ValueError,TypeError) as e: print(json.dumps({"error":str(e)}),file=sys.stderr);return 2
if __name__=="__main__": raise SystemExit(main())
